#whSheet{position:fixed;inset:0;z-index:10001;background:rgba(17,10,35,.5);-webkit-backdrop-filter:blur(7px);backdrop-filter:blur(7px);
  display:none;align-items:flex-end;justify-content:center;padding:0 10px calc(10px + env(safe-area-inset-bottom))}
#whSheet.on{display:flex;animation:svcFade .2s}
.whbox{position:relative;background:#fff;border-radius:34px;padding:22px 20px 18px;width:100%;max-width:480px;text-align:center;
  box-shadow:0 24px 60px rgba(20,12,40,.35);animation:askUp .4s cubic-bezier(.2,1.15,.3,1)}
.wh-x{position:absolute;top:16px;left:16px;width:36px;height:36px;border-radius:50%;border:0;background:#F3F1F8;color:#6E6787;display:grid;place-items:center}
